COPY={}
def page(n,en,es,se,ss,ce,cs,fe,fs):
 COPY[f'DD-{n:03d}']={'en':dict(title=en[0],intro=en[1],sections=se,checklist=ce,faq=fe),'es':dict(title=es[0],intro=es[1],sections=ss,checklist=cs,faq=fs)}
page(19,('Doberman size and growth: standards are not growth targets','Use breed standards to understand adult conformation, then track your own dog’s growth with consistent observations and veterinary guidance. A puppy does not need to match an internet weight table at every age.'),('Tamaño y crecimiento: el estándar no es una meta de desarrollo','Usa estándares para comprender conformación adulta y registra crecimiento individual con observaciones coherentes y orientación veterinaria. Un cachorro no necesita coincidir con una tabla de internet a cada edad.'),[
('Name the standard you are comparing','The AKC standard gives adult height at the withers as 26–28 inches for males and 24–26 inches for females. These are conformation criteria, not a puppy growth schedule or a diagnosis. The FCI publishes a separate standard; keep the organization and units attached to any comparison.'),('Measure consistently and comfortably','For height, use level nonslip ground and a natural standing posture, measuring vertically to the highest point of the withers rather than the top of the head. Do not force a worried dog into position. For weight, use an appropriate scale and ask your veterinary team how to obtain useful comparable readings.'),('Track trends alongside everyday observations','Record date, measurement method and units, together with appetite, activity and any concerns. Compare repeated observations rather than one surprising value from a different scale or posture. Body condition and growth deserve professional interpretation; a larger number does not automatically mean better development.'),('A worked record example','Illustrative entry: date—your measurement day; weight—your scale reading in kilograms; method—same clinic scale; observation—eating and moving as usual; question—ask whether the trend and body condition fit this dog. The example deliberately supplies no target puppy weight and does not diagnose normality.'),('Ask for help instead of trying to accelerate growth','Discuss unexpected changes, poor intake, discomfort or a concern about growth with your veterinarian. Do not add supplements or change feeding merely to reach a breed-size target. Measurements also help with equipment fitting, but the dog’s comfort and current dimensions matter more than a predicted adult size.')],[
('Identifica el estándar','AKC indica altura adulta a la cruz de 26–28 pulgadas para machos y 24–26 para hembras. Son criterios de conformación, no calendario de cachorro ni diagnóstico. FCI tiene otro estándar; conserva organización y unidades al comparar.'),('Mide con coherencia y comodidad','Utiliza suelo nivelado antideslizante y postura natural. Mide verticalmente hasta la cruz, no hasta la cabeza. No fuerces postura si preocupa. Para peso, usa báscula adecuada y pide al equipo veterinario cómo obtener lecturas comparables.'),('Registra tendencias y observaciones','Anota fecha, método y unidades junto a apetito, actividad y dudas. Compara observaciones repetidas, no una cifra sorprendente de otra báscula o postura. Condición corporal y crecimiento requieren interpretación; más peso no siempre significa mejor desarrollo.'),('Ejemplo de registro','Fecha: día de medición; peso: lectura propia en kilogramos; método: misma báscula clínica; observación: come y se mueve como siempre; pregunta: si tendencia y condición encajan con este perro. No ofrece peso objetivo ni diagnostica normalidad.'),('Consulta sin acelerar crecimiento','Habla de cambios inesperados, mala ingesta, molestias o dudas con el veterinario. No añadas suplementos ni cambies comida solo para alcanzar talla. Las medidas ayudan con equipo, pero importan dimensiones actuales y comodidad.')],['Keep the organization and units beside any standard.','Use a consistent comfortable measurement method.','Record trends and questions without diagnosing.','Ask your veterinarian about growth or condition concerns.'],['Conserva organización y unidades del estándar.','Utiliza método coherente y cómodo.','Registra tendencias y preguntas sin diagnosticar.','Consulta crecimiento o condición al veterinario.'],[('Should a puppy match an adult standard now?','No. Adult conformation criteria are not age-by-age growth targets.'),('Can a weight chart prove my dog is healthy?','No. Measurements need individual context and veterinary interpretation.')],[('¿Debe cumplir el estándar adulto ahora?','No. Conformación adulta no es objetivo de crecimiento por edad.'),('¿Una tabla demuestra salud?','No. Las medidas necesitan contexto e interpretación individual.')])
page(20,('Doberman colors and coat: read the named standard','Color terminology depends on the registration standard. Learn the labels, keep appearance separate from health assessment and avoid choosing a dog on a rare-color claim alone.'),('Colores y pelaje: consulta el estándar concreto','La terminología depende del estándar de registro. Aprende etiquetas, separa aspecto y valoración de salud y no elijas solo por una promesa de color raro.'),[
('Separate AKC and FCI terminology','The AKC standard permits black, red, blue and fawn (Isabella), with rust markings. The FCI standard describes black and brown with defined rust-red markings. Read the named organization’s actual document rather than treating one list as universal across registries.'),('Use visual labels cautiously','The color tiles below are simplified illustrations of terminology, not photographs or a genetic identification tool. Lighting, screens and coat variation affect appearance. The natural-ear portrait on this page illustrates a black-and-rust dog; it does not show every color listed.'),('Look at the coat beyond its color','Observe comfort, visible skin and changes in shedding or hair coverage. A photo cannot identify the cause of irritation or hair loss. Share persistent scratching, thinning or new changes with your veterinarian instead of assuming color explains them or choosing a treatment from an online image.'),('A worked seller-claim check','Example: a listing says a color is recognized everywhere. Ask which registry and standard it refers to, request identifying records and compare the claim with the official document. Recognition is a registration question; it is not proof of health, breeding quality or suitability for your home.'),('Choose evidence beyond appearance','Ask about the individual dog’s history, care needs, health records and the breeder’s raising practices. A premium price or rarity label cannot answer those questions. Keep coat-care tasks gentle and suitable for the dog rather than assuming a color requires an unreviewed product routine.')],[
('Distingue AKC y FCI','AKC admite negro, rojo, azul y leonado (Isabella), con marcas fuego. FCI describe negro y marrón con marcas rojo óxido definidas. Consulta la organización concreta sin convertir una lista en universal.'),('Interpreta ilustraciones con cuidado','Los cuadros inferiores simplifican términos; no son fotografías ni identifican genética. Luz, pantalla y variación alteran aspecto. El retrato con orejas naturales muestra negro y fuego, no todos los colores.'),('Observa más que color','Revisa comodidad, piel visible y cambios de muda o cobertura. Una foto no identifica irritación ni pérdida de pelo. Consulta rascado persistente, zonas con menos pelo o cambios nuevos sin atribuirlos automáticamente al color.'),('Ejemplo de comprobación','Un anuncio afirma reconocimiento en todas partes. Pregunta registro y estándar, pide identificación y compara documento oficial. Reconocimiento no demuestra salud, calidad de crianza ni adecuación al hogar.'),('Busca evidencia más allá del aspecto','Pregunta historia, cuidados, registros y crianza. Precio o rareza no responden. Mantén cuidados suaves adecuados, sin asumir que el color exige productos no revisados.')],['Identify the registration standard behind a color claim.','Distinguish illustrations from identification evidence.','Ask for individual records, not rarity promises.','Discuss new coat or skin concerns with your veterinarian.'],['Identifica estándar detrás de la afirmación.','Distingue ilustración y evidencia de identificación.','Pide registros individuales, no promesas de rareza.','Consulta cambios nuevos de pelo o piel.'],[('Are the same colors recognized by every registry?','No. Compare the named AKC and FCI documents and any applicable registry requirements.'),('Does a recognized color prove good health?','No. Registration criteria and an individual health assessment answer different questions.')],[('¿Todos los registros reconocen lo mismo?','No. Compara documentos AKC, FCI y requisitos correspondientes.'),('¿Color reconocido demuestra salud?','No. Registro y valoración individual responden preguntas distintas.')])
page(21,('European versus American Dobermans: ask about the actual dog','Treat geographic labels as a starting point for questions about registration and ancestry. They do not reliably tell you whether an individual dog will be easy to live with, healthy or suited to a particular job.'),('Dóberman europeo y americano: pregunta por el perro real','Usa etiquetas geográficas para preguntar por registro y ascendencia. No indican de forma fiable facilidad de convivencia, salud ni adecuación a una tarea.'),[
('Ask what the geographic label means','A seller may mean the place a dog was born, recent ancestors, a registry or a particular breeding line. Request the specific meaning and identifying records. Do not assume that every dog born in Europe follows one breeding program or that an imported ancestor establishes temperament.'),('Compare documents rather than photo stereotypes','AKC and FCI publish separate conformation standards. They provide context for registration and evaluation, including differences in color terminology, but neither document is a prediction of an individual puppy’s behavior. Read current official documents before repeating a simplified online comparison.'),('Look for specific behavioral evidence','Ask what is known about the parents, the puppy’s raising environment, ordinary handling and responses in everyday settings. Observe the individual through an appropriate arrangement with the breeder or rescue. Avoid claims that one country’s dogs are automatically aggressive, calmer or more trainable.'),('A worked comparison question','Example: two sellers use different geographic labels. Ask each for parent identifiers, screening records, descriptions of raising practices and written support arrangements. Compare the evidence and unresolved questions side by side. A larger head in a photo cannot replace those checks or establish working ability.'),('Match your home to needs you can support','Consider your experience, time, safe management and access to qualified help. Choose on verified information and the individual dog’s needs rather than a prestige label. Health-screening interpretation belongs with your veterinary team, and suitability cannot be guaranteed from ancestry alone.')],[
('Aclara la etiqueta geográfica','Puede significar nacimiento, antepasados, registro o línea de crianza. Pide significado y registros. Nacer en Europa no implica un solo programa, y un antepasado importado no determina temperamento.'),('Compara documentos, no estereotipos','AKC y FCI publican estándares distintos. Contextualizan registro y evaluación, incluidas diferencias de color, pero no predicen conducta del cachorro. Lee documentos oficiales antes de repetir comparaciones simplificadas.'),('Solicita evidencia de conducta','Pregunta progenitores, entorno de crianza, manejo y respuestas cotidianas. Observa al individuo mediante un acuerdo apropiado. Evita afirmar que un país produce siempre perros agresivos, tranquilos o más entrenables.'),('Ejemplo comparativo','Dos vendedores usan etiquetas distintas. Pide identificadores, pruebas, crianza y apoyo escrito. Compara evidencia y preguntas pendientes. Una cabeza mayor en foto no sustituye comprobaciones ni demuestra capacidad de trabajo.'),('Valora necesidades y hogar','Considera experiencia, tiempo, manejo seguro y apoyo. Elige información verificada y necesidades individuales, no prestigio. Consulta interpretación de pruebas al veterinario; ascendencia no garantiza adecuación.')],['Ask exactly what the geographic label describes.','Request ancestry, registration and screening records.','Compare raising practices and individual observations.','Choose supportable needs rather than stereotypes.'],['Aclara qué describe la etiqueta.','Pide ascendencia, registro y pruebas.','Compara crianza y observaciones individuales.','Valora necesidades en vez de estereotipos.'],[('Does European mean more aggressive?','No geographic label establishes an individual dog’s behavior. Ask for specific history and appropriate assessment.'),('Can I identify ancestry from a photo?','Appearance alone cannot verify the claimed pedigree or registration.')],[('¿Europeo significa más agresivo?','La etiqueta no determina conducta individual. Pide historia y valoración apropiadas.'),('¿Identifico ascendencia por foto?','El aspecto no verifica pedigrí ni registro.')])
